const fs = require('node:fs');
const path = require('node:path');
const files = [];
for (const dir of ['src', 'test']) {
  for (const f of fs.readdirSync(dir)) {
    if (f.endsWith('.js')) files.push(path.join(dir, f));
  }
}
let renameCount = 0, attemptCount = 0;
const changed = [];
for (const f of files) {
  const src = fs.readFileSync(f, 'utf8');
  const r = src.match(/\bretryPolicy\b/g)?.length ?? 0;
  const a = src.match(/\bmaxAttempts: 3\b/g)?.length ?? 0;
  if (r === 0 && a === 0) continue;
  let out = src.replace(/\bretryPolicy\b/g, 'backoffPolicy').replace(/\bmaxAttempts: 3\b/g, 'maxAttempts: 5');
  fs.writeFileSync(f, out);
  renameCount += r; attemptCount += a;
  changed.push(`${f} (rename ${r}, attempts ${a})`);
}
const leftover = await $`grep -rn "retryPolicy" src test; echo "leftover-exit=$?"`;
const test = await $`node --test 2>&1; echo "exit=$?"`;
return { filesScanned: files.length, renameCount, attemptCount, changed, leftover: leftover.stdout, test: test.stdout.slice(-3000) };

